from collections import deque
fives={(r,c) for r in range(H) for c in range(W) if inp[r][c]==5}
def comp(seed, allow):
    seen={seed};q=deque([seed])
    while q:
        r,c=q.popleft()
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if dr or dc:
                    n=(r+dr,c+dc)
                    if 0<=n[0]<H and 0<=n[1]<W and n in allow and n not in seen:
                        seen.add(n);q.append(n)
    return seen
